"""Base provider abstraction and data models for AEGIS-CORE LLM integrations.

Ensures that the Mini AI Agent execution loop is decoupled from specific vendor SDKs.
"""

from abc import ABC, abstractmethod
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field


class ToolCall(BaseModel):
    """Normalized tool call request generated by an LLM."""

    model_config = ConfigDict(extra="ignore")

    id: str = Field(..., description="Unique tool call invocation ID")
    name: str = Field(..., description="Name of the tool requested by the model")
    arguments: str = Field(..., description="Raw JSON string containing tool arguments")


class ChatMessage(BaseModel):
    """Normalized chat message passed to and returned from providers."""

    model_config = ConfigDict(extra="ignore")

    role: Literal["system", "user", "assistant", "tool"] = Field(
        ..., description="Message role in conversation context"
    )
    content: str | None = Field(
        default=None, description="Textual content of the message"
    )
    tool_calls: list[ToolCall] = Field(
        default_factory=list,
        description="Tool calls requested by the assistant message",
    )
    tool_call_id: str | None = Field(
        default=None,
        description="Identifier of tool call being responded to (required if role is tool)",
    )
    name: str | None = Field(
        default=None,
        description="Name of tool being responded to",
    )


class LLMResponse(BaseModel):
    """Standardized response envelope returned by all LLM providers."""

    model_config = ConfigDict(extra="ignore")

    content: str | None = Field(
        default=None, description="Text response from the model"
    )
    tool_calls: list[ToolCall] = Field(
        default_factory=list, description="List of tool calls requested by model"
    )
    finish_reason: str | None = Field(
        default=None, description="Reason model stopped (e.g. 'stop', 'tool_calls')"
    )
    model: str | None = Field(
        default=None, description="Model identifier that produced the completion"
    )
    usage: dict[str, int] = Field(
        default_factory=dict, description="Token consumption metrics"
    )

    @property
    def has_tool_calls(self) -> bool:
        """Check whether the response includes tool call requests."""
        return len(self.tool_calls) > 0


# ---------------------------------------------------------------------------
# Provider Exceptions
# ---------------------------------------------------------------------------


class ProviderError(Exception):
    """Base exception for all LLM provider failures."""


class ProviderConfigError(ProviderError):
    """Raised when provider configuration or credentials are missing or invalid."""


class ProviderTimeoutError(ProviderError):
    """Raised when an LLM API request times out."""


class ProviderAPIError(ProviderError):
    """Raised when an external LLM API returns an error or fails unexpectedly."""


# ---------------------------------------------------------------------------
# Base Provider Abstract Class
# ---------------------------------------------------------------------------


class BaseLLMProvider(ABC):
    """Abstract interface defining required provider capabilities."""

    @property
    @abstractmethod
    def provider_name(self) -> str:
        """Name of the provider implementation (e.g. 'openai', 'fake')."""

    @property
    @abstractmethod
    def model_name(self) -> str:
        """Active model identifier."""

    @abstractmethod
    def generate(
        self,
        messages: list[ChatMessage],
        tools: list[dict[str, Any]] | None = None,
    ) -> LLMResponse:
        """Generate a completion for the provided message sequence and tool schemas.

        Args:
            messages: Conversation history.
            tools: Optional OpenAI-compatible tool specifications.

        Returns:
            Standardized LLMResponse.

        Raises:
            ProviderConfigError: If provider lacks valid configuration or API keys.
            ProviderTimeoutError: If the request exceeds configured timeout.
            ProviderAPIError: If upstream API fails or returns an error.
        """
